begin;
insert into auth.users(id) values('00000000-0000-0000-0000-000000000971'),('00000000-0000-0000-0000-000000000972'),('00000000-0000-0000-0000-000000000973');
insert into profiles(id) values('00000000-0000-0000-0000-000000000971'),('00000000-0000-0000-0000-000000000972');
do $$declare v_tarefa uuid;v_tarefa2 uuid;v_run jsonb;v_cliente uuid;v_antes bigint;begin
 select count(*) into v_antes from public.clientes;
 if has_schema_privilege('authenticated','homologacao','usage') then raise exception 'Homologação exposta';end if;
 if has_function_privilege('authenticated','public.clara_m1_aprovar(uuid,uuid)','execute') then raise exception 'Aprovação pública';end if;
 begin perform public.clara_m1_receber('00000000-0000-0000-0000-000000000973',repeat('1',64),'Cadastrar','teste.txt','Fictício');raise exception 'Usuário inativo aceito';exception when insufficient_privilege then null;end;
 begin perform public.clara_m1_receber('00000000-0000-0000-0000-000000000971',repeat('1',64),'Cadastrar','teste.txt','Fictício');raise exception 'Ambiente desativado aceito';exception when raise_exception then if sqlerrm<>'Homologação Clara desativada' then raise;end if;end;
 update homologacao.clara_config set habilitado=true where id;
 v_tarefa:=public.clara_m1_receber('00000000-0000-0000-0000-000000000971',repeat('1',64),'Cadastrar','teste.txt','Nome fictício');
 if public.clara_m1_receber('00000000-0000-0000-0000-000000000971',repeat('1',64),'Cadastrar','teste.txt','Nome fictício')<>v_tarefa then raise exception 'Intake duplicado';end if;
 if (select count(*) from homologacao.clara_eventos where tarefa_id=v_tarefa)<>4 then raise exception 'Transições iniciais ausentes ou duplicadas';end if;
 begin perform public.clara_m1_consultar('00000000-0000-0000-0000-000000000972',v_tarefa);raise exception 'Tarefa vazou para outro gestor';exception when insufficient_privilege then null;end;
 v_run:=public.clara_m1_reservar('00000000-0000-0000-0000-000000000971',v_tarefa);
 if v_run is null then raise exception 'Não reservou';end if;
 if public.clara_m1_reservar('00000000-0000-0000-0000-000000000971',v_tarefa) is not null then raise exception 'Execução duplicada';end if;
 if public.clara_m1_previa('00000000-0000-0000-0000-000000000971',v_tarefa,gen_random_uuid(),'{}','{}','[]',null,1,1,0) then raise exception 'Aceitou consumo de outra tentativa';end if;
 perform public.clara_m1_previa('00000000-0000-0000-0000-000000000971',v_tarefa,(v_run->>'consumo_id')::uuid,'{"nome":"Cliente Ficticia Clara Teste","cpf_cnpj":"00000000191","email":"clara.m1@example.invalid"}','{"nome":"Nome fictício"}','[]',null,100,50,.00012);
 if exists(select 1 from homologacao.clientes) then raise exception 'Gravou antes da aprovação';end if;
 v_cliente:=(public.clara_m1_aprovar('00000000-0000-0000-0000-000000000971',v_tarefa)->>'cliente_id')::uuid;
 if v_cliente is null or not exists(select 1 from homologacao.clientes where id=v_cliente and status='prospecto' and not ativo) then raise exception 'Cadastro nativo não confirmado';end if;
 if (public.clara_m1_aprovar('00000000-0000-0000-0000-000000000971',v_tarefa)->>'cliente_id')::uuid<>v_cliente then raise exception 'Aprovação repetida duplicou';end if;
 if public.clara_m1_reservar('00000000-0000-0000-0000-000000000971',v_tarefa) is not null then raise exception 'IA repetida após conclusão';end if;
 v_tarefa2:=public.clara_m1_receber('00000000-0000-0000-0000-000000000971',repeat('2',64),'Cadastrar','outro.txt','Outro TXT, mesma pessoa fictícia');
 v_run:=public.clara_m1_reservar('00000000-0000-0000-0000-000000000971',v_tarefa2);
 perform public.clara_m1_previa('00000000-0000-0000-0000-000000000971',v_tarefa2,(v_run->>'consumo_id')::uuid,'{"nome":"Cliente Ficticia Clara Teste","cpf_cnpj":"00000000191","email":"clara.m1@example.invalid"}','{}','[]',null,80,40,.0001);
 if (public.clara_m1_aprovar('00000000-0000-0000-0000-000000000971',v_tarefa2)->>'cliente_id')::uuid<>v_cliente then raise exception 'Duplicou por outro TXT';end if;
 if (select count(*) from homologacao.clientes)<>1 then raise exception 'Duplicou cliente';end if;
 v_tarefa2:=public.clara_m1_receber('00000000-0000-0000-0000-000000000971',repeat('3',64),'Cadastrar','falha.txt','Falha fictícia');
 v_run:=public.clara_m1_reservar('00000000-0000-0000-0000-000000000971',v_tarefa2);
 perform public.clara_m1_consumo('00000000-0000-0000-0000-000000000971',v_tarefa2,(v_run->>'consumo_id')::uuid,50,10,.000036);
 perform public.clara_m1_falhar('00000000-0000-0000-0000-000000000971',v_tarefa2,(v_run->>'consumo_id')::uuid,'JSON de teste inválido');
 if not exists(select 1 from homologacao.clara_tarefas where id=v_tarefa2 and estado='failed' and tokens_entrada+tokens_saida=60) then raise exception 'Perdeu custo de resposta inválida';end if;
 v_run:=public.clara_m1_reservar('00000000-0000-0000-0000-000000000971',v_tarefa2);
 update homologacao.clara_tarefas set atualizado_em=now()-interval '11 minutes' where id=v_tarefa2;
 if not public.clara_m1_recuperar('00000000-0000-0000-0000-000000000971',v_tarefa2) then raise exception 'Não recuperou interrupção';end if;
 v_run:=public.clara_m1_reservar('00000000-0000-0000-0000-000000000971',v_tarefa2);
 perform public.clara_m1_falhar('00000000-0000-0000-0000-000000000971',v_tarefa2,(v_run->>'consumo_id')::uuid,'Falha fictícia');
 if public.clara_m1_reservar('00000000-0000-0000-0000-000000000971',v_tarefa2) is not null then raise exception 'Ultrapassou tentativas';end if;
 if (select count(*) from public.clientes)<>v_antes then raise exception 'Alterou clientes de produção';end if;
 if exists(select 1 from homologacao.clara_eventos where motivo like '%00000000191%' or motivo like '%example.invalid%') then raise exception 'PII no log';end if;
end;$$;
rollback;
